mapper.select:
SELECT usage_id, user_idx, ip_address, period_start, session_count, message_count
FROM ADMIN_ASSISTANT_DAILY_USAGE
WHERE period_start = #{periodStart}

      AND user_idx = #{userIdx}
      AND ip_address = #{ipAddress}

LIMIT 1

mapper.update:
UPDATE ADMIN_ASSISTANT_DAILY_USAGE
   SET message_count = GREATEST(0, message_count - #{amount})
 WHERE period_start = #{periodStart}

    AND user_idx = #{userIdx}
    AND ip_address = #{ipAddress}
